    nl: {
      metadata: {
        title: 'T Golf Calvià Review (2026) - Greenfees, Baancondities & Eerlijke Beoordeling',
        description: 'T Golf Calvià beoordeeld door een PGA Professional die in mei 2026 speelde. Tot €210 piekperiode, twilight vanaf €150. 15 meren, 6.500m vanaf de achterste tees, 9/10 conditie.',
        imagePath: '/images/t-golf-calvia-social.jpg',
      },
      meta: {
        badge: 'Baanreview',
        badgeGold: true,
        readTime: '6 min',
        updated: 'Mei 2026',
        title: 'T Golf Calvià Review - De Eerlijke Mening van een PGA Professional (2026)',
        intro: 'Vijftien meren, windmolens door de hele baan en enkele van de zuiverste greens die ik op Mallorca heb gespeeld. Een 9 uit 10 en een van de best onderhouden banen op het eiland.',
        related: [
          { slug: 'son-gual-review', title: 'Son Gual Golf: Eerlijke Review 2026' },
          { slug: 'son-muntaner-review', title: 'Son Muntaner Golf: Eerlijke Review 2026' },
          { slug: 'best-golf-courses-mallorca', title: 'Beste Golfbanen op Mallorca 2026' },
          { slug: 'golf-cost-mallorca', title: 'Wat kost golf op Mallorca?' },
        ],
      },
      blocks: [
        { type: 'image', alt: 'Windmolen op T Golf Calvià tegen een heldere blauwe lucht', caption: 'De windmolens zijn een onderscheidend kenmerk van T Golf Calvià.' },
        { type: 'paragraph', text: 'Ik sloeg om 15:20 af op een dinsdagmiddag en de baan was stil genoeg om de wind door de pijnbomen te horen tussen de slagen door. Vanaf de meeste fairways zie je geen weg of gebouw, alleen pijnbomen, water en bergen. Voor een baan in de zuidwestelijke hoek van Mallorca verraste me dat.' },
        { type: 'paragraph', text: 'De conditie is zo goed als alles wat ik op het eiland heb gespeeld. Zeer kort gemaaide fairways en fringe, bunkers perfect geharkt, en een eenvoudig maar ongebruikelijk harkontwerp waarbij de bal zelden tegen de hark tot stilstand komt. Het is een klein detail, maar een dat echt gewaardeerd wordt.' },
        { type: 'image', alt: 'Bunker op T Golf Calvià met het kenmerkende harkontwerp', caption: 'Het harkontwerp zorgt ervoor dat de bal zelden tegen de rand tot stilstand komt. Een klein detail dat echt verschil maakt.' },
        { type: 'paragraph', text: 'De greens zijn groot en waren op de dag dat ik speelde vlekkeloos. Geen excuses voor gemiste putts. Op meerdere holes moet je ook volledig vertrouwen op je afstand omdat je de onderkant van de vlag niet kunt zien vanaf de approach. Spelers die op de vlagpositie vertrouwen voor afstandsbepaling in plaats van op yards te werken, worden verrast.' },
        { type: 'paragraph', text: 'De baan meet iets minder dan 6.500 meter vanaf de achterste tees waar ik speelde, met 15 meren en carries vanaf de tee op meerdere holes. Windmolens staan verspreid over de hele baan, wat ongebruikelijk is en de baan een eigen karakter geeft. De mediterrane pijnbomen en de Tramuntana-bergen zijn constant aanwezig van de voornegen tot de terugweg.' },
        { type: 'image', alt: 'Fairway op T Golf Calvià met windmolen en Tramuntana-bergen op de achtergrond', caption: 'De windmolens en het Tramuntana-decor zijn een constant kenmerk tijdens de hele ronde.' },
        { type: 'heading', text: 'Holes om te kennen' },
        { type: 'paragraph', text: 'Hole 7 is een dogleg door de bomen. Kort op de kaart, maar de approach-afstand is moeilijker in te schatten dan het lijkt en spelers nemen vaak een te kort club.' },
        { type: 'paragraph', text: 'Hole 8 is een dalende par 4 met een smalle landingszone vanaf de tee. De approach is een hanteerbare wedge als je de fairway vindt, maar mis je hem en een voorste vlag wordt snel ingewikkeld. De helling maakt het moeilijk om de bal te stoppen.' },
        { type: 'image', alt: 'Hole 8 op T Golf Calvià met palmbomen en Tramuntana-bergen achter de green', caption: 'Hole 8. Een goed decor, maar de approach vraagt meer dan het lijkt.' },
        { type: 'paragraph', text: 'Hole 10 is de duidelijkste beslissing op de baan. Dogleg rechts met een windmolen links en water rechts. Je kunt afstand afsnijden over het water afhankelijk van hoeveel risico je wilt nemen. Het is het soort hole dat anders speelt afhankelijk van waar je bent in de ronde.' },
        { type: 'image', alt: 'Fairway en bunkers op T Golf Calvià met de Tramuntana-bergen op de achtergrond', caption: 'De Tramuntana-bergen liggen op de achtergrond bij de meeste holes van de terugweg.' },
        { type: 'paragraph', text: 'Hole 16 is een par 4 met een opgaande tee-shot omlijst door rotsen en bomen. Een van de visueel meest onderscheidende holes op de baan en hij speelt moeilijker dan de kaart suggereert.' },
        { type: 'paragraph', text: 'Hole 18 is een smalle par 5 die opentrekt naarmate je de fairway afloopt. Het is een echte slotshole. Hij vraagt commitment vanaf de tee die smal lijkt, en beloont je als je het doet.' },
        { type: 'image', alt: 'Twee golfers op de baan bij T Golf Calvià met de fairway en bergen achter hen', caption: 'T Golf Calvià spelen met een gast. De baan is geschikt voor spelers die een serieuze uitdaging in goede conditie willen.' },
        { type: 'heading', text: 'Praktische Informatie' },
        { type: 'facts', items: [['Tot €210', 'Piekperiode greenfee'], ['Vanaf €150', 'Twilight tarief'], ['9/10', "Andy's beoordeling"], ['6.500m', 'Achterste tees (Par 72)']] },
        { type: 'paragraph', text: 'T Golf Calvià heeft regelmatig doordeweekse en meervoudig-bezoek aanbiedingen. De moeite waard om te controleren voor je boekt: t-golf.club/calvia/offers.' },
        { type: 'paragraph', text: 'De service was gedurende de hele ronde goed. Tees en water beschikbaar, vriendelijk caddy master personeel. Het clubhuis en de buitenruimtes zijn goed uitgevoerd en een prettige plek om tijd door te brengen voor of na de ronde. De driving range is op gras, wat niet bij elke Mallorca club gegarandeerd is.' },
        { type: 'paragraph', text: 'Één punt om op te letten: de bewegwijzering rond beperkte buggygebieden kan duidelijker. Een paar keer bevond ik me ergens dat niet duidelijk als verboden was aangegeven en moest ik achteruit. Geen probleem als je de baan kent.' },
        { type: 'image', alt: 'Pijnbomen die de fairway omlijsten op T Golf Calvià met water en bergen zichtbaar daarboven', caption: 'Vanaf de meeste fairways zie je niets anders dan pijnbomen, water en bergen.' },
        { type: 'heading', text: 'Conclusie' },
        { type: 'paragraph', text: '9/10. T Golf Calvià is een van de best onderhouden banen die ik op Mallorca heb gespeeld. De greens zijn uitstekend, de fairways in goede conditie, en de indeling test je serieus, met name rond afstandsbeoordeling en water, zonder oneerlijk te zijn.' },
        { type: 'paragraph', text: 'Het is geschikt voor spelers die een serieuze ronde in goede conditie willen. Ik zou een hoog-handicapper hier niet naartoe sturen als eerste baan van een vakantie, maar voor iedereen op een dedicated golfbezoek hoort het op het programma. Het twilight tarief en de doordeweekse aanbiedingen maken het op het juiste moment goede waar voor het geld.' },
        { type: 'cta', text: 'Wil je T Golf Calvià spelen met een PGA professional die elke hole kent?', linkLabel: 'Bekijk de play-with-a-pro ervaring →' },
      ],
    },
